{"packet_id":"D032-01","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken Rent Control Ordinance","requirement":"Rents are controlled at the October 1, 1985 base rent; no increase may be demanded or accepted except as the chapter allows, and increases at any other time or above the allowed amount are void. Landlords must give 30 days' written notice.","key_value":null,"coverage_conditions":"Applies to all dwelling units as defined, except motels/hotels, newly constructed dwellings on first rental, industrial, commercial and nonresidential property, school/college student housing, government-owned housing, buildings vacant since January 1, 1984, and multiple dwellings constructed after June 25, 1987.","applicability":{"conditions":[{"type":"built","role":"exempt","op":"after","date":"1987-06-25","basis":"construction","conditional":true},{"type":"other","text":"newly constructed dwellings exempt for the first rental if registered before first rental"},{"type":"other","text":"buildings completely vacant since January 1, 1984 (must register before renting)"},{"type":"owner","role":"exempt","who":"school, college or similar institution","unit_limit":null},{"type":"owner","role":"exempt","who":"state or federal government","unit_limit":null}],"per_tenancy":null,"coverage_quotes":["This chapter shall apply to all dwelling units as defined in § 155-1 above, except that the following shall be exempt:","the provisions of this chapter shall not apply to multiple dwellings, as defined in the statute, constructed after June 25, 1987, for a period not to exceed the period of amortization of any initial mortgage loan obtained for the multiple dwelling or for 30 years following completion of construction, whichever is less."]},"exemptions":"Motels and hotels; newly constructed dwellings for the first rental; industrial and commercial/nonresidential property; school or college student housing; government-owned housing; buildings vacant since January 1, 1984; multiple dwellings constructed after June 25, 1987 for up to 30 years.","penalty":"Excess rents are null and void and must be refunded or credited to the tenant; a refund or credit is barred if the tenant does not request a legal rent calculation within two years of service of the disclosure statement.","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 155-4","quoted_span":"All rents for rental of housing space and services in dwellings to which this act is applicable are hereby controlled at the base rent level received by the landlord as of October 1, 1985, and no rental increases shall be hereinafter demanded, paid or accepted, except as provided in this chapter.","interaction":"Chapter is preempted while a governmental agency contract regulates rents, and multiple dwellings constructed after June 25, 1987 are exempt under N.J.S.A. 2A:42-84.1 et seq. for up to 30 years.","relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D032-01","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"just_cause_eviction","lifecycle":"enacted","title":"Hoboken just cause for eviction definition","requirement":"A landlord may recover possession of a housing space or dwelling only for one of the reasons outlined in New Jersey State law (N.J.S.A. 2A:18-53, as amended).","key_value":null,"coverage_conditions":"Housing space or dwelling subject to the Hoboken Rent Control Ordinance.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 155-1","quoted_span":"JUST CAUSE FOR EVICTION — The landlord recovered possession of a housing space or dwelling for one of the reasons outlined in New Jersey State law (N.J.S.A. 2A:18-53 as amended).","interaction":null,"relations":[],"confidence":0.5,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D032-01","n_rules":2,"note":null}

